    // MARK: Primitive rules

    @Test func recordCountersAreStrictAndExhaustBeforeMax() throws {
        let key = SymmetricKey(size: .bits256)
        let th = Data(repeating: 7, count: 32)
        let sender = TransportRecordCipher(key: key, th: th, direction: 2, counter: UInt64.max - 1)
        let record = try sender.seal(Data("last".utf8), final: false)
        #expect(record.counter == UInt64.max - 1)
        #expect(throws: TransportCryptoError("record counter exhausted")) { try sender.seal(Data(), final: false) }
        let receiver = TransportRecordCipher(key: key, th: th, direction: 2, counter: UInt64.max - 1)
        #expect(throws: TransportCryptoError.self) { try receiver.open(counter: 0, ciphertext: record.ciphertext, final: false) }
        // Wrong final flag fails authentication without advancing the counter.
        #expect(throws: TransportCryptoError.self) {
            try receiver.open(counter: record.counter, ciphertext: record.ciphertext, final: true)
        }
        #expect(try receiver.open(counter: record.counter, ciphertext: record.ciphertext, final: false) == Data("last".utf8))
        receiver.dispose()
        #expect(throws: TransportCryptoError("cipher disposed")) { try receiver.open(counter: 0, ciphertext: Data(count: 16), final: false) }
    }

    @Test func oversizedFrameIsRejectedWithoutConsumingACounter() throws {
        let v = try protocolVector("x25519")
        let channel = try wsChannel(v, maxFrameBytes: 100)
        let limit = TransportSizeCheck.webSocketPlaintextLimit(maxFrameBytes: 100)
        #expect(throws: TransportPayloadTooLargeError(size: limit + 1, limit: limit)) {
            try channel.seal(String(repeating: "x", count: limit + 1))
        }
        // The next frame still uses counter 0, exactly as in the vector.
        let first = v["ws"]["frames"].arrayValue[0]
        #expect(try channel.seal(first["plaintext"].stringValue) == (try hex(first["frame"])))
        #expect(TransportSizeCheck.webSocketPlaintextLimit() == 8 * 1024 * 1024 - 24)
    }

